const D = [width, height, depth], fw = Math.min(frame_width, Math.min(...D) / 3), n = Math.max(1, Math.round(planks)), t = 0.02, rec = Math.min(0.015, fw / 3);
for (const ax of [0, 1, 2]) for (const sg of [-1, 1]) {
  const run = ax === 0 ? 2 : 0, st = ax === 1 ? 2 : 1;
  const L = D[run] - 2 * rec, w = Math.max(0.005, (D[st] - 2 * rec - (n - 1) * gap) / n);
  for (let i = 0; i < n; i++) {
    const p = [0, 0, 0], s = [0, 0, 0];
    p[ax] = sg * (D[ax] / 2 - rec - t / 2); p[st] = -D[st] / 2 + rec + (i + 0.5) * w + i * gap;
    s[ax] = t; s[run] = L; s[st] = w;
    p[1] += D[1] / 2;
    const q = addpoint(0, p);
    setpointattrib(0, 'scale', q, s);
    setpointattrib(0, 'tint', q, 0.82 + 0.3 * rand(ax * 2 + sg, i, seed));
  }
}

const D = [width, height, depth], fw = Math.min(frame_width, Math.min(...D) / 3);
for (const a of [0, 1, 2]) {
  const b = (a + 1) % 3, c = (a + 2) % 3;
  for (const sb of [-1, 1]) for (const sc of [-1, 1]) {
    const p = [0, 0, 0], s = [fw, fw, fw];
    p[b] = sb * (D[b] - fw) / 2; p[c] = sc * (D[c] - fw) / 2;
    s[a] = a === 1 ? D[a] : D[a] - 2 * fw;
    p[1] += D[1] / 2;
    const q = addpoint(0, p);
    setpointattrib(0, 'scale', q, s);
    setpointattrib(0, 'tint', q, 1);
  }
}
